architecture.h4_f:
msg = CBOR{v:1, teks, reply_to, sent_at}
ct = AES-GCM-256-Encrypt(k, nonce, msg, aad=room_id)
POST /api/rooms/{id}/messages {ciphertext: hex(ct), nonce: hex}

cryptoWire.h1_f:
pt = CBOR{v:1, teks, reply_to?, thread_id?, mentions?, sent_at}
ct = AES-GCM-256-Encrypt(room_key, nonce, pt, aad=hex(room_id))
wayar = CBOR{
  v: 1,
  teks sifir: hex(ct), // panjang berubah-ubah
  nonce: hex(12 B),
  pengirim_pseudo: hex(16 B),
  dihantar_di: unix_ms
}

cryptoWire.h5_f:
luar = CBOR{
  source_node: hex32,
  pengguna_sasaran: int64,
  inner_ciphertext: bait,
  inner_nonce: bait,
  dihantar_di: unix_ms
}
sig = Ed25519-Sign(source_priv, outer)
POST /persekutuan/hantar { sampul surat: luar, tanda: hex64 }

auth.h1_f:
POST /api/authentication/register
  { nama pengguna, kata laluan, x25519_public_key, display_name, telefon?, e-mel?, avatar_emoji }

Respons 201 Dibuat:
  { access_token, refresh_token, user_id, username, ... }

auth.h3_f:
muatan_token akses:
  { sub: user_id, jti: device_id, type: "access", exp: now + 15min }
refresh_token muatan:
  { sub: user_id, jti: device_id, taip: "refresh", exp: now + 30h }

HS256-ditandatangani dengan rahsia 64-bait nod daripada .env

auth.h4_f:
register_begin(): cabaran = rand(32)
                    pilihan = { rp.id, user.id, pubKeyCredParams, cabaran }
                    pilihan pulangan

register_finish(atestasi):
  sahkan pengesahan terhadap TPM / akar Enklaf Selamat CA
  kedai { credential_id, public_key, counter: 0 }

auth.h7_f:
POST /api/authentication/qr/begin
  → { nonce: 128-bit hex, ttl: 60 }
QR muatan = { tidak, id_pengguna, pelayan: "https://node.example" }

POST /api/authentication/qr/verify { tidak pernah }
  → peranti baru didaftarkan; JWT kembali.

rooms.h6_f:
sender_pseudo = HMAC-SHA256(room_pseudo_salt, sender_id)[:16] // 32 hex
ciphertext = AES-GCM-Encrypt(room_key, nonce, CBOR_payload, aad=room_id)

Bingkai kipas: { type:"m", bilik, msg:{id, ct, nonce, sender_pseudo, sent_at} }

files.h2_f:
init POST /api/files/resumable/init {nama fail, saiz, chunk_size_hint}
            ← {upload_id, chunk_size}
ketul PUT /api/files/resumable/{upload_id}/chunk/{offset} <ct bytes>
            ← 204
finalize POST /api/files/resumable/{upload_id}/finalise {plain_blake3}
            ← 201 {file_id, url}
TTL pada belum selesai: 24 jam

files.h4_f:
nafi_senarai = {
  "aplikasi/x-dosexec",
  "aplikasi/x-sharedlib",
  "aplikasi/x-mach-binary",
}
jika magic.from_buffer(buf[:1024]) dalam deny_list: return 415

presence.h1_f:
klien: pada ketukan kekunci pertama → hantar {type:"t", state:"start"}
         tiada lagi penghantaran selama 3 saat melainkan keadaan berubah
         10 s selepas ketukan kekunci terakhir → hantar {type:"t", state:"stop"}
penerima: hentian automatik 10 saat selepas "mula" terakhir jika tiada "berhenti" tiba

calls.h1_f:
POST /api/calls/{room_id}/start {video, audio} → call_id
WS siaran {type:"c", kind:"invite", call_id}
WS siaran {type:"c", kind:"offer", sdp}
WS siaran {type:"c", kind:"answer", sdp}
WS siaran {type:"c", kind:"calon",ice} × N
POST /api/calls/{call_id}/end

federation.h2_f:
sampul surat = {
  source_node : hex32,
  pengguna_sasaran : int64,
  inner_ciphertext: bait,
  inner_nonce : bait,
  sent_at : unix_ms,
}
sig = Ed25519Sign(sumber_priv, CBOR(sampul surat))
POST /persekutuan/hantar { sampul surat, tanda }

gossip.h3_f:
iklan = {pubkey, endpoint, advertised_at}
sig = Ed25519-Sign(pubkey_priv, CBOR(iklan))
muatan gosip: [..., {ad, sig}, ...]

penerima: sahkan sig terhadap ad.pubkey → simpan jika ok
tambahan: PoW sebanyak 2^18 sifar pendahulu pada {pubkey, endpoint}

stealth.h2_f:
bait ClientHello = chrome_120_template dengan {
  rawak = rawak kami,
  server_name = nama hos kami (atau ECH-dibalut),
  session_id = id sesi kami,
}
JA4 = t13d_xxxx_xxxx_xxxx (padan dengan stabil Chrome semasa)

stealth.h4_f:
DoH: POST https://cloudflare-dns.com/dns-query {nama: x.vortexx.sol}
ECH: ClientHello.extensions += encrypted_sni(public_key_from_HTTPS_record)
DGA: domain(t) = base32( SHA256(benih ∥ YYYY-MM-DD) )[:16] + ".contoh"

push.h4_f:
iOS NSE: didReceive(permintaan) { nyahsulit(request.content.userInfo) }
Android FCM: onMessageReceived(remoteMessage) { decrypt(remoteMessage.data) }
Web SW: self.addEventListener('push', e => menyahsulit(e.data))

controller.h2_f:
alat = alat_tanda
input = pokok sumber, kunci/kunci.kunci
nyata = {
  versi: "0.1.0",
  built_at: unix_ms,
  fail: [{path, sha256, size}, ...]
}
sig = Ed25519-Sign(release_priv, CBOR(manifest))
output = INTEGRITY.sig.json = {manifes, ditandatangani_oleh: pub_hex, sig: sig_hex}

bots.h1_f:
buat: POST /api/bots {nama pengguna, nama_pameran, kod}
          → {bot_id, token, pubkey}
jalankan: dalam proses (coroutine dalam nod)
      OR luaran (tinjauan panjang /api/bots/{id}/kemas kini, pengesahan token)
mesej: {teks, tandatangan: Ed25519-Sign(bot_priv, canonical_msg)}

bots.h2_f:
pada /mula {
  keluarkan "Selamat Datang, {ctx.first_name}"
}
pada /tambah <item> {
  state.list = (state.list atau []) + [ctx.args.item]
  mengeluarkan "Ditambah: {ctx.args.item}"
}

security.h4_f:
canary.txt (setiap hari):
  {tarikh, tanda: Ed25519-Sign(release_priv, date)}
klien mengesahkan → tidak hadir atau tidak sah ⇒ kompromi disyaki

kecemasan:
  admin POST /api/admin/revoke-all {sebab}
  siaran nod {type:"n", event:"compromise", reason}
  pelanggan mengelap kekunci, memaksa semula bootstrap

